BEGIN IMMEDIATE;
ALTER TABLE journals ADD COLUMN source TEXT NOT NULL DEFAULT 'manual' CHECK(source IN ('manual','document','close'));
CREATE TABLE parties (id INTEGER PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('customer','supplier')), contact TEXT NOT NULL, account_id INTEGER NOT NULL REFERENCES accounts(id));
CREATE TABLE numbering (kind TEXT PRIMARY KEY, prefix TEXT NOT NULL, next INTEGER NOT NULL CHECK(next>0));
INSERT INTO numbering VALUES ('sale','INV-',1),('purchase','BILL-',1),('receipt','RCPT-',1),('payment','PAY-',1),('stock','STK-',1),('close','CLOSE-',1);
CREATE TABLE items (id INTEGER PRIMARY KEY, code TEXT NOT NULL COLLATE NOCASE UNIQUE, name TEXT NOT NULL, unit TEXT NOT NULL, asset_account_id INTEGER NOT NULL REFERENCES accounts(id), expense_account_id INTEGER NOT NULL REFERENCES accounts(id));
CREATE TABLE documents (id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('sale','purchase','receipt','payment','stock')), number TEXT NOT NULL UNIQUE, date TEXT NOT NULL, party_id INTEGER REFERENCES parties(id), invoice_id INTEGER REFERENCES documents(id), journal_id INTEGER UNIQUE REFERENCES journals(id), total_minor INTEGER NOT NULL CHECK(total_minor>0), request_id TEXT NOT NULL UNIQUE, request_payload TEXT NOT NULL, data TEXT NOT NULL);
CREATE INDEX documents_party ON documents(party_id,date,id);
CREATE TABLE stock_moves (id INTEGER PRIMARY KEY, item_id INTEGER NOT NULL REFERENCES items(id), document_id INTEGER NOT NULL REFERENCES documents(id), quantity_milli INTEGER NOT NULL CHECK(quantity_milli!=0), value_minor INTEGER NOT NULL, CHECK((quantity_milli>0 AND value_minor>=0) OR (quantity_milli<0 AND value_minor<=0)));
CREATE INDEX stock_item ON stock_moves(item_id,document_id);
CREATE TABLE periods (id INTEGER PRIMARY KEY, start TEXT NOT NULL, end TEXT NOT NULL UNIQUE, journal_id INTEGER UNIQUE REFERENCES journals(id), equity_account_id INTEGER NOT NULL REFERENCES accounts(id));
CREATE TABLE reconciliations (id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES accounts(id), start TEXT NOT NULL, end TEXT NOT NULL, opening_minor TEXT NOT NULL, closing_minor TEXT NOT NULL, reference TEXT NOT NULL, request_id TEXT NOT NULL UNIQUE, request_payload TEXT NOT NULL);
CREATE TABLE cleared_lines (line_id INTEGER PRIMARY KEY REFERENCES lines(id), reconciliation_id INTEGER NOT NULL REFERENCES reconciliations(id));
CREATE TRIGGER period_post_guard BEFORE UPDATE OF status ON journals WHEN NEW.status='posted' AND EXISTS(SELECT 1 FROM periods WHERE NEW.date<=end) BEGIN SELECT RAISE(ABORT,'This financial period is closed'); END;
CREATE TRIGGER document_no_update BEFORE UPDATE ON documents BEGIN SELECT RAISE(ABORT,'Posted documents are immutable'); END;
CREATE TRIGGER document_no_delete BEFORE DELETE ON documents BEGIN SELECT RAISE(ABORT,'Posted documents are immutable'); END;
CREATE TRIGGER stock_no_update BEFORE UPDATE ON stock_moves BEGIN SELECT RAISE(ABORT,'Stock movements are immutable'); END;
CREATE TRIGGER stock_no_delete BEFORE DELETE ON stock_moves BEGIN SELECT RAISE(ABORT,'Stock movements are immutable'); END;
CREATE TRIGGER party_no_update BEFORE UPDATE ON parties BEGIN SELECT RAISE(ABORT,'Party definitions are immutable'); END;
CREATE TRIGGER party_no_delete BEFORE DELETE ON parties BEGIN SELECT RAISE(ABORT,'Party definitions are immutable'); END;
CREATE TRIGGER item_no_update BEFORE UPDATE ON items BEGIN SELECT RAISE(ABORT,'Item definitions are immutable'); END;
CREATE TRIGGER item_no_delete BEFORE DELETE ON items BEGIN SELECT RAISE(ABORT,'Item definitions are immutable'); END;
CREATE TRIGGER period_no_update BEFORE UPDATE ON periods BEGIN SELECT RAISE(ABORT,'Closed periods are immutable'); END;
CREATE TRIGGER period_no_delete BEFORE DELETE ON periods BEGIN SELECT RAISE(ABORT,'Closed periods are immutable'); END;
CREATE TRIGGER reconciliation_no_update BEFORE UPDATE ON reconciliations BEGIN SELECT RAISE(ABORT,'Statements are immutable'); END;
CREATE TRIGGER reconciliation_no_delete BEFORE DELETE ON reconciliations BEGIN SELECT RAISE(ABORT,'Statements are immutable'); END;
CREATE TRIGGER cleared_no_update BEFORE UPDATE ON cleared_lines BEGIN SELECT RAISE(ABORT,'Cleared lines are immutable'); END;
CREATE TRIGGER cleared_no_delete BEFORE DELETE ON cleared_lines BEGIN SELECT RAISE(ABORT,'Cleared lines are immutable'); END;
CREATE TRIGGER journal_no_direct_post BEFORE INSERT ON journals WHEN NEW.status='posted' BEGIN SELECT RAISE(ABORT,'Post journals through validated draft transition'); END;
CREATE TRIGGER party_account_kind_guard BEFORE UPDATE OF kind ON accounts WHEN EXISTS(SELECT 1 FROM parties WHERE account_id=OLD.id) OR EXISTS(SELECT 1 FROM items WHERE asset_account_id=OLD.id OR expense_account_id=OLD.id) BEGIN SELECT RAISE(ABORT,'Mapped account types are immutable'); END;
PRAGMA user_version = 2;
COMMIT;
